mapper.select:
select  from business_audit_event
where cast(domain_type as binary)=cast('REGISTRATION' as binary) and domain_id=#{registrationId}
  and cast(target_type as binary)=cast('CMS_REGISTRATION' as binary) and target_id=#{registrationId}
  and cast(action as binary) in ('REGISTRATION_STATION_REDEEM','REGISTRATION_REDEEM','GROUP_MEMBER_REDEEM','REGISTRATION_VERIFY_REVERSE')
order by id for update
